/**
 * Centralized Shared Emoji System (Eara Monochrome Architecture)
 * Single source of truth for all emojis across components, embeds, and commands.
 * Zero duplication. 100% static, monochrome white vector emojis synced from guild.
 */

const fs = require("fs");
const path = require("path");

// Load custom synced emojis if present (generated by scripts/deploy-monochrome-emojis.js)
let customEmojis = {};
const customPath = path.join(__dirname, "customEmojis.json");
if (fs.existsSync(customPath)) {
  try {
    customEmojis = JSON.parse(fs.readFileSync(customPath, "utf-8"));
  } catch {}
}

const DEFAULT_EMOJIS = {
  // Player Transport Controls (100% Monochrome White Static)
  player: {
    previous: customEmojis.previous || "⏮️",
    play: customEmojis.play || customEmojis.playpause || "▶️",
    pause: customEmojis.pause || customEmojis.playpause || "⏸️",
    playpause: customEmojis.playpause || "⏯️",
    skip: customEmojis.skip || "⏭️",
    stop: customEmojis.stop || "⏹️",
    loop: customEmojis.loop || "🔁",
    loopOne: customEmojis.loop_one || customEmojis.loopOne || "🔂",
    shuffle: customEmojis.shuffle || "🔀",
    autoplay: customEmojis.autoplay || "♾️",
    save: customEmojis.heart || customEmojis.save || "🤍",
    heart: customEmojis.heart || "🤍",
    openPlayer: customEmojis.openPlayer || "⏫",
    queue: customEmojis.queue || "📑",
  },

  // Eara Sleek Seamless Progress Bar Elements
  progress: {
    filled: "▰",
    empty: "▱",
    dot: "🔘",
    lineFilled: "━",
    lineEmpty: "─",
  },

  // Volume & Audio Levels (100% Monochrome White Static)
  volume: {
    mute: customEmojis.volumemute || customEmojis.volumeMute || "🔇",
    low: customEmojis.volumelow || customEmojis.volumeLow || "🔉",
    normal: customEmojis.volume || customEmojis.volumeNormal || "🔊",
    boost: customEmojis.volume || customEmojis.volumeBoost || "📢",
  },

  // DSP Audio Filters & Presets
  filters: {
    spatial8D: customEmojis.dj || "🎧",
    bass: customEmojis.volume || "💥",
    nightcore: customEmojis.sparkles || "⚡",
    vaporwave: customEmojis.disc || "🌊",
    karaoke: customEmojis.music || "🎤",
    pop: customEmojis.music || "🎵",
    rock: customEmojis.music || "🎸",
    normalizer: customEmojis.disc || "🎚️",
    reset: customEmojis.loop || "🔄",
  },

  // Streaming Platforms & Sources (Monochrome White Static Branding)
  platforms: {
    spotify: customEmojis.spotify || "⚪",
    youtube: customEmojis.youtube || "⚪",
    soundcloud: customEmojis.soundcloud || "⚪",
    jiosaavn: customEmojis.music || "⚪",
    bandcamp: customEmojis.disc || "⚪",
    twitch: customEmojis.radio || "⚪",
    web: customEmojis.disc || "🌐",
    music: customEmojis.music || "🎶",
  },

  // Status, Alerts & Highlights (Monochrome White Static)
  status: {
    success: customEmojis.check || "✅",
    error: customEmojis.cross || "❌",
    warn: "⚠️",
    info: "ℹ️",
    sparkles: customEmojis.sparkles || "✨",
    fire: customEmojis.fire || "🔥",
    pin: "📌",
  },

  // Bot Features & Navigation
  features: {
    dj: customEmojis.dj || "🎧",
    voteskip: customEmojis.check || "🗳️",
    playlist: customEmojis.queue || "📁",
    lyrics: customEmojis.music || "📜",
    search: customEmojis.music || "🔍",
    time: "⏱️",
    user: "👤",
    link: "🔗",
    stats: "📊",
    ping: "📡",
    disc: customEmojis.disc || "💿",
    radio: customEmojis.radio || "📻",
    equalizer: "🎛️",
  },
};

// Create a unified, flattened shared dictionary for clean imports
const emojis = {
  ...DEFAULT_EMOJIS,

  // Flattened shortcuts for convenience
  ...DEFAULT_EMOJIS.player,
  ...DEFAULT_EMOJIS.volume,
  ...DEFAULT_EMOJIS.status,
  ...DEFAULT_EMOJIS.features,

  // Direct Aliases
  check: DEFAULT_EMOJIS.status.success,
  cross: DEFAULT_EMOJIS.status.error,
  alert: DEFAULT_EMOJIS.status.warn,
  volumeHigh: DEFAULT_EMOJIS.volume.normal,
  volumeMute: DEFAULT_EMOJIS.volume.mute,
  volumeLow: DEFAULT_EMOJIS.volume.low,
  speaker: DEFAULT_EMOJIS.volume.boost,

  /**
   * Helper to format readable platform badge with emoji
   */
  getPlatformBadge(sourceName) {
    const src = (sourceName || "").toLowerCase();
    switch (src) {
      case "spotify":
        return `${DEFAULT_EMOJIS.platforms.spotify} Spotify`;
      case "youtube":
        return `${DEFAULT_EMOJIS.platforms.youtube} YouTube`;
      case "soundcloud":
        return `${DEFAULT_EMOJIS.platforms.soundcloud} SoundCloud`;
      case "jiosaavn":
        return `${DEFAULT_EMOJIS.platforms.jiosaavn} JioSaavn`;
      case "bandcamp":
        return `${DEFAULT_EMOJIS.platforms.bandcamp} Bandcamp`;
      case "twitch":
        return `${DEFAULT_EMOJIS.platforms.twitch} Twitch`;
      case "http":
      case "https":
        return `${DEFAULT_EMOJIS.platforms.web} Web Stream`;
      default:
        return `${DEFAULT_EMOJIS.platforms.music} Audio`;
    }
  },

  /**
   * Helper to get appropriate volume emoji for level percentage
   */
  getVolumeEmoji(level) {
    if (level === 0) return DEFAULT_EMOJIS.volume.mute;
    if (level < 50) return DEFAULT_EMOJIS.volume.low;
    if (level <= 100) return DEFAULT_EMOJIS.volume.normal;
    return DEFAULT_EMOJIS.volume.boost;
  },

  /**
   * Helper to build progress bar with custom Discord server emojis or clean Unicode fallback
   */
  createProgressBar(current, total, size = 12) {
    if (!total || total === 0 || isNaN(total) || total === Infinity) {
      return "⚪ `[LIVE STREAM]`";
    }
    const clampedCurrent = Math.min(Math.max(current, 0), total);
    const progress = Math.min(Math.max(clampedCurrent / total, 0), 1);
    const filledBlocks = Math.round(progress * size);

    // Seamless custom monochrome server emojis (Eara exact match)
    if (customEmojis.bar_lf && customEmojis.bar_le) {
      let bar = "";
      for (let i = 0; i < size; i++) {
        const isFirst = i === 0;
        const isLast = i === size - 1;
        const isFilled = i < filledBlocks;

        if (isFirst) {
          if (filledBlocks === 1 && customEmojis.bar_single_f) {
            bar += customEmojis.bar_single_f;
          } else {
            bar += isFilled ? customEmojis.bar_lf : customEmojis.bar_le;
          }
        } else if (isLast) {
          bar += isFilled ? customEmojis.bar_rf : customEmojis.bar_re;
        } else {
          bar += isFilled ? customEmojis.bar_mf : customEmojis.bar_me;
        }
      }
      return bar;
    }

    // High quality Unicode fallback
    const emptyProgress = Math.max(0, size - filledBlocks);
    const filled = DEFAULT_EMOJIS.progress.filled.repeat(Math.max(0, filledBlocks));
    const empty = DEFAULT_EMOJIS.progress.empty.repeat(emptyProgress);

    return `${filled}${empty}`;
  },
};

module.exports = emojis;
